"""Unified PISM inverse modeling driver.

Supports SSA, SSA+SIA (hybrid), and Blatter stress balance inversions
for basal yield stress (tauc) or vertically-averaged ice hardness (hardav).

The stress balance solver is selected via the ``stress_balance.model``
configuration parameter (``ssa``, ``ssa+sia``, or ``blatter``).

Usage
-----
::

    pismi -i STATE.nc -inv_data OBS.nc -o OUT.nc \\
        -stress_balance.model ssa \\
        -inverse.design.variable tauc \\
        -inv_method tikhonov_lmvm \\
        [other PISM and PETSc options]

For Blatter inversions, add Blatter-specific solver options::

    pismi -i STATE.nc -inv_data OBS.nc -o OUT.nc \\
        -stress_balance.model blatter \\
        -inverse.design.variable hardav \\
        -inv_method tikhonov_lmvm \\
        -stress_balance.blatter.Mz 10 \\
        -bp_pc_type mg -bp_mg_levels_pc_type jacobi ...
"""

import PISM
import PISM.invert.core as core
import PISM.invert.ssa
import PISM.invert.blatter
from PISM.logging import logMessage
from PISM.util import convert, Bunch
from mpi4py import MPI
import gc
import sys
import os
import traceback


# ============================================================================
# Helper functions
# ============================================================================

def adjustTauc(mask, tauc):
    """Set tauc to zero where floating and to a high value where ice-free.

    Parameters
    ----------
    mask : CellType array
        Ice mask (grounded, floating, ice-free).
    tauc : Scalar array
        Basal yield stress to adjust in place.
    """
    logMessage("  Adjusting initial estimate of 'tauc' to match PISM model"
               " for floating ice and ice-free bedrock.\n")
    grid = mask.grid()
    high_tauc = grid.ctx().config().get_number(
        "basal_yield_stress.ice_free_bedrock")
    with PISM.vec.Access(comm=tauc, nocomm=mask):
        for (i, j) in grid.points():
            if mask.ocean(i, j):
                tauc[i, j] = 0
            elif mask.ice_free(i, j):
                tauc[i, j] = high_tauc


def createDesignVec(grid, design_var, name=None, **kwargs):
    """Create a design variable vector (tauc or hardav).

    Parameters
    ----------
    grid : Grid
        PISM grid.
    design_var : str
        ``'tauc'`` or ``'hardav'``.
    name : str, optional
        Variable name override.

    Returns
    -------
    Scalar array
        The design variable vector.
    """
    if name is None:
        name = design_var
    if design_var == "tauc":
        return PISM.model.createYieldStressVec(grid, name=name, **kwargs)
    elif design_var == "hardav":
        return PISM.model.createAveragedHardnessVec(grid, name=name, **kwargs)
    else:
        raise ValueError("Unknown design variable %s" % design_var)


# ============================================================================
# Solver factories
# ============================================================================

def create_forward_run(solver_type, input_filename, inv_data_filename,
                       design_var, design_filename=None, ensure_hardav=False):
    """Create the appropriate forward-run object for the solver type.

    Parameters
    ----------
    solver_type : str
        One of ``'ssa'``, ``'ssa+sia'``, ``'blatter'``.
    input_filename : str
        Path to the PISM state file.
    inv_data_filename : str
        Path to the inverse data file (observed velocities).
    design_var : str
        Design variable name (``'tauc'`` or ``'hardav'``).
    design_filename : str, optional
        File to read the design fields (``tauc``, ``hardav``) from, taking
        precedence over the input file (Blatter only; used by alternating
        inversions to pick up the previous phase's result).
    ensure_hardav : bool, optional
        Compute ``hardav`` from enthalpy if no ``hardav`` field is available
        (Blatter only).

    Returns
    -------
    SSAForwardRunFromInputFile or BlatterForwardRunFromInputFile
        The forward-run object.
    """
    if solver_type in ('ssa', 'ssa+sia'):
        return PISM.invert.ssa.SSAForwardRunFromInputFile(
            input_filename, inv_data_filename, design_var)
    elif solver_type == 'blatter':
        return PISM.invert.blatter.BlatterForwardRunFromInputFile(
            input_filename, inv_data_filename, design_var,
            design_filename=design_filename, ensure_hardav=ensure_hardav)
    else:
        raise ValueError(
            "Unknown solver type '%s'. "
            "Expected 'ssa', 'ssa+sia', or 'blatter'." % solver_type)


def create_solver(solver_type, forward_run):
    """Create the appropriate inverse solver for the solver type.

    Parameters
    ----------
    solver_type : str
        One of ``'ssa'``, ``'ssa+sia'``, ``'blatter'``.
    forward_run : SSAForwardRun or BlatterForwardRun
        The forward-run setup.

    Returns
    -------
    InvSolver
        The inverse solver instance.
    """
    if solver_type in ('ssa', 'ssa+sia'):
        return PISM.invert.ssa.createInvSSASolver(forward_run)
    elif solver_type == 'blatter':
        return PISM.invert.blatter.createInvBlatterSolver(forward_run)
    else:
        raise ValueError("Unknown solver type '%s'." % solver_type)


# ============================================================================
# Main driver
# ============================================================================

# ============================================================================
# Inversion driver
# ============================================================================

# Human-readable names of the design variables (used in metadata).
_DESIGN_LONG_NAMES = {'tauc': 'basal yield stress',
                      'hardav': 'vertically-averaged ice hardness'}

# Order of the phases within one alternation cycle.
_ALTERNATION_PHASES = ('tauc', 'hardav')

# Global attribute recording the last completed alternation phase.
_ALTERNATION_ATTR = 'pismi_alternation_completed'


def _read_global_attribute(filename, name):
    """Return the text global attribute ``name`` of ``filename`` ('' if absent)."""
    ds = PISM.File(PISM.Context().com, filename,
                   PISM.PISM_NETCDF3, PISM.PISM_READONLY)
    try:
        return ds.read_text_attribute("PISM_GLOBAL", name)
    finally:
        ds.close()


def _write_global_attribute(filename, name, value):
    """Set the text global attribute ``name`` of ``filename`` to ``value``."""
    ds = PISM.File(PISM.Context().com, filename,
                   PISM.PISM_NETCDF3, PISM.PISM_READWRITE)
    try:
        ds.redef()
        ds.write_attribute("PISM_GLOBAL", name, value)
    finally:
        ds.close()


def _first_file_with(candidates, varname):
    """Return the first file in ``candidates`` containing ``varname`` (or ``None``)."""
    for filename in candidates:
        if filename and PISM.util.fileHasVariable(filename, varname):
            return filename
    return None


def _run_phase(opts, design_var, restart=False, cycle=None):
    """Run one inversion for a single design variable.

    Parameters
    ----------
    opts : Bunch
        Options parsed by :func:`_run` (file names, flags, solver type).
    design_var : str
        ``'tauc'`` or ``'hardav'``.
    restart : bool
        Resume this phase from its last saved ``zeta``.
    cycle : int, optional
        Alternation cycle index; ``None`` for a single-design-variable run.
        In alternation mode the *other* design variable is read from the
        output file (the result of the previous phase), ``zeta`` is stored
        as ``zeta_inv_<design_var>`` and the iteration history is stored with
        a ``_c<cycle>_<design_var>`` suffix.

    Returns
    -------
    float or None
        Misfit of the last iteration (``inv_misfit`` or ``inv_J_misfit``),
        or ``None`` if the solver did not report any.
    """
    context = PISM.Context()
    config = context.config
    com = context.com

    input_filename = opts.input_filename
    inv_data_filename = opts.inv_data_filename
    output_filename = opts.output_filename
    saving_inv_data = opts.saving_inv_data
    alternating = cycle is not None

    if alternating:
        tag = "c%d_%s" % (cycle, design_var)
        suffix = "_" + tag
        zeta_name = "zeta_inv_%s" % design_var
        logMessage("=== Alternation cycle %d: inverting for %s (%s) ===\n"
                   % (cycle, design_var, _DESIGN_LONG_NAMES[design_var]))
    else:
        suffix = ""
        zeta_name = "zeta_inv"

    # ── Set up the forward problem ────────────────────────────────────

    # Make sure a column-constant hardness exists when it is needed: as the
    # design variable, or (when alternating) as an input of the tauc phase.
    forward_run = create_forward_run(
        opts.solver_type, input_filename, inv_data_filename, design_var,
        design_filename=output_filename if alternating else None,
        ensure_hardav=(alternating or design_var == 'hardav'))
    forward_run.setup()

    design_param = forward_run.designVariableParameterization()
    solver = create_solver(opts.solver_type, forward_run)

    modeldata = forward_run.modeldata
    vecs = modeldata.vecs
    grid = modeldata.grid

    # Write the grid mapping variable (CRS / spatial_ref) if available and
    # not present yet.
    mapping = grid.get_mapping_info()
    if (mapping.has_attributes()
            and not PISM.util.fileHasVariable(output_filename,
                                              mapping.get_name())):
        F = PISM.util.prepare_output(output_filename, append_time=False,
                                     append=True)
        F.define_variable(mapping)
        F.close()

    # ── Design variable prior ─────────────────────────────────────────

    design_prior = createDesignVec(grid, design_var,
                                   '%s_prior' % design_var)
    long_name = design_prior.metadata().get_string("long_name")
    design_prior.metadata().long_name(
        "best prior estimate for %s (used for inversion)" % long_name)

    regrid_filename = config.get_string("input.regrid.file")
    regrid_vars = set(filter(
        None, config.get_string("input.regrid.vars").split(",")))

    # The prior stays anchored to the original inputs: in alternation mode
    # the output file is consulted last, and only for the `<var>_prior`
    # copy written by an earlier phase (never for the inverted `<var>`).
    prior_candidates = []
    if opts.use_design_prior:
        prior_candidates.append(inv_data_filename)
    if alternating:
        prior_candidates.append(output_filename)
    prior_source = _first_file_with(prior_candidates, '%s_prior' % design_var)

    if prior_source is not None:
        logMessage("  Reading '%s_prior' from %s.\n"
                   % (design_var, prior_source))
        design_prior.regrid(prior_source, critical=True)
        vecs.add(design_prior, writing=(saving_inv_data or alternating))
    else:
        # Honor `-input.regrid.file` / `-input.regrid.vars`: if the design
        # variable is listed there, read it from the regrid file. Falls
        # back to the bootstrap input file otherwise (and, when alternating,
        # to the field an earlier phase wrote to the output file).
        design_candidates = []
        if regrid_filename and design_var in regrid_vars:
            design_candidates.append(regrid_filename)
        design_candidates.append(input_filename)
        if alternating:
            design_candidates.append(output_filename)
        design_source = _first_file_with(design_candidates, design_var)
        if design_source is not None:
            logMessage("Reading '%s_prior' from '%s' in %s.\n"
                       % (design_var, design_var, design_source))
            design = createDesignVec(grid, design_var)
            design.regrid(design_source, True)
            design_prior.copy_from(design)
        elif design_var == 'hardav' and vecs.has('hardav'):
            # No hardness in any file: use the one derived from enthalpy by
            # the forward run (see BlatterForwardRunFromInputFile).
            logMessage("Using 'hardav' derived from enthalpy as "
                       "'hardav_prior'.\n")
            design_prior.copy_from(vecs.hardav)
        else:
            PISM.verbPrintf(1, com,
                            "Initial guess for design variable is not "
                            "available as '%s' in %s.\n"
                            % (design_var, ", ".join(design_candidates)))
            exit(1)
        vecs.add(design_prior, writing=True)

    # In alternation mode the first (tauc) phase records the hardness it
    # used as `hardav_prior`, so that the hardav phases have a fixed prior
    # even when the input file provides no `hardav`.
    if (alternating and design_var == 'tauc' and vecs.has('hardav')
            and not PISM.util.fileHasVariable(output_filename, 'hardav_prior')):
        hardav_prior = createDesignVec(grid, 'hardav', 'hardav_prior')
        hardav_prior.copy_from(vecs.hardav)
        hardav_prior.metadata().long_name(
            "best prior estimate for %s (used for inversion)"
            % _DESIGN_LONG_NAMES['hardav'])
        vecs.add(hardav_prior, writing=True)
        logMessage("  Saving the hardness used by the tauc phase as "
                   "'hardav_prior'.\n")

    # ── Fixed design-variable mask ────────────────────────────────────

    if opts.using_zeta_fixed_mask:
        if PISM.util.fileHasVariable(inv_data_filename, "zeta_fixed_mask"):
            zeta_fixed_mask = PISM.model.createZetaFixedMaskVec(grid)
            # Use nearest-neighbor interpolation so the mask stays 0/1
            # at boundaries (bilinear would produce fractional values).
            zeta_fixed_mask.set_interpolation_type(PISM.NEAREST)
            zeta_fixed_mask.regrid(inv_data_filename)
            vecs.add(zeta_fixed_mask)
        else:
            logMessage("  Computing 'zeta_fixed_mask'.\n")
            zeta_fixed_mask = PISM.model.createZetaFixedMaskVec(grid)
            zeta_fixed_mask.set(1)
            mask = vecs.mask
            if design_var == 'tauc':
                # Basal yield stress only matters under grounded ice.
                with PISM.vec.Access(comm=zeta_fixed_mask, nocomm=mask):
                    for (i, j) in grid.points():
                        if mask.grounded_ice(i, j):
                            zeta_fixed_mask[i, j] = 0
                vecs.add(zeta_fixed_mask)
                adjustTauc(vecs.mask, design_prior)
            elif design_var == 'hardav':
                # Hardness controls the flow wherever there is ice
                # (including floating ice, where basal drag vanishes);
                # it has no meaning at ice-free cells.
                with PISM.vec.Access(comm=zeta_fixed_mask, nocomm=mask):
                    for (i, j) in grid.points():
                        if mask.icy(i, j):
                            zeta_fixed_mask[i, j] = 0
                vecs.add(zeta_fixed_mask)
            else:
                raise NotImplementedError(
                    "Unable to build 'zeta_fixed_mask' for %s."
                    % design_var)

    # ── Convert prior -> zeta ─────────────────────────────────────────

    zeta_prior = PISM.Scalar2(grid, "zeta_prior")
    design_param.convertFromDesignVariable(design_prior, zeta_prior)
    vecs.add(zeta_prior, writing=True)

    # ── Initial guess for zeta ────────────────────────────────────────

    zeta = PISM.Scalar2(grid, zeta_name)
    zeta.metadata(0).long_name(zeta_name).units("1").output_units("1")

    if restart:
        if not PISM.util.fileHasVariable(output_filename, zeta_name):
            PISM.verbPrintf(1, com,
                            "Unable to restart: file %s missing '%s'\n"
                            % (output_filename, zeta_name))
            exit(1)
        logMessage("  Restarting from '%s' in %s\n" % (zeta_name, output_filename))
        zeta.regrid(output_filename, True)
    elif alternating and PISM.util.fileHasVariable(output_filename, design_var):
        # Continue from the result of the previous phase / cycle.
        logMessage("  Starting from '%s' in %s\n" % (design_var, output_filename))
        design = createDesignVec(grid, design_var)
        design.regrid(output_filename, True)
        design_param.convertFromDesignVariable(design, zeta)
    elif PISM.util.fileHasVariable(inv_data_filename, zeta_name):
        logMessage("  Starting from '%s' in %s\n" % (zeta_name, inv_data_filename))
        zeta.regrid(inv_data_filename, True)
    else:
        zeta.copy_from(zeta_prior)

    # ── Load observed velocities ──────────────────────────────────────

    vel_observed = PISM.model.create2dVelocityVec(
        grid, '_observed', stencil_width=2)

    if PISM.util.fileHasVariable(inv_data_filename, "u_observed"):
        vel_observed.regrid(inv_data_filename, True)
        vecs.add(vel_observed, writing=saving_inv_data)
    elif PISM.util.fileHasVariable(inv_data_filename, "u_ssa_observed"):
        # Legacy variable name fallback
        vel_observed.metadata(0).set_name("u_ssa_observed")
        vel_observed.metadata(1).set_name("v_ssa_observed")
        vel_observed.regrid(inv_data_filename, True)
        vel_observed.metadata(0).set_name("u_observed")
        vel_observed.metadata(1).set_name("v_observed")
        vecs.add(vel_observed, writing=saving_inv_data)
    else:
        PISM.verbPrintf(1, com,
                        "No observed velocities (u/v_observed or "
                        "u/v_ssa_observed) found in %s.\n"
                        % inv_data_filename)
        exit(1)

    # ── Optionally subtract SIA from observations (SSA/hybrid only) ──

    if opts.remove_sia and opts.solver_type in ('ssa', 'ssa+sia'):
        has_velsurf = (
            PISM.util.fileHasVariable(input_filename, "uvelsurf") and
            PISM.util.fileHasVariable(input_filename, "vvelsurf"))
        has_vel_ssa = (
            PISM.util.fileHasVariable(input_filename, "u_ssa") and
            PISM.util.fileHasVariable(input_filename, "v_ssa"))
        if has_velsurf and has_vel_ssa:
            vel_surf = PISM.model.create2dVelocityVec(
                grid, '_surf_tmp', stencil_width=2)
            vel_surf.metadata(0).set_name("uvelsurf")
            vel_surf.metadata(1).set_name("vvelsurf")
            vel_surf.regrid(input_filename, True)

            vel_ssa_model = PISM.model.create2dVelocityVec(
                grid, '_ssa_tmp', stencil_width=2)
            vel_ssa_model.metadata(0).set_name("u_ssa")
            vel_ssa_model.metadata(1).set_name("v_ssa")
            vel_ssa_model.regrid(input_filename, True)

            # SIA = velsurf - vel_ssa; then observed -= SIA
            vel_surf.add(-1, vel_ssa_model)
            vel_observed.add(-1, vel_surf)
            logMessage("  Subtracted SIA component (velsurf - vel_ssa)"
                       " from observed velocities.\n")
        else:
            PISM.verbPrintf(1, com,
                            "WARNING: -remove_sia set but input file "
                            "missing uvelsurf/vvelsurf or u_ssa/v_ssa."
                            " Skipping.\n")

    # ── Load true design variable if available (synthetic tests) ──────

    if PISM.util.fileHasVariable(inv_data_filename,
                                  "%s_true" % design_var):
        design_true = createDesignVec(grid, design_var,
                                       '%s_true' % design_var)
        design_true.regrid(inv_data_filename, True)
        vecs.add(design_true, writing=saving_inv_data)

    zeta.write(output_filename)

    # ── Attach iteration listeners ────────────────────────────────────

    solver.addIterationListener(core.printIteration)

    misfit_logger = core.MisfitLogger()
    solver.addIterationListener(misfit_logger)

    if opts.inv_method.startswith('tikhonov'):
        solver.addIterationListener(core.printTikhonovProgress)

    solver.addDesignUpdateListener(
        core.ZetaSaver(output_filename, zeta_name,
                       _DESIGN_LONG_NAMES[design_var]))

    # ── Run the inverse solver ────────────────────────────────────────

    if restart:
        logMessage('************** Restarting inversion. '
                   '****************\n')
    else:
        logMessage('============== Starting inversion '
                   '(%s, design variable %s). ==================\n'
                   % (opts.solver_type, design_var))

    reason = solver.solveInverse(zeta_prior, vel_observed, zeta)
    if reason.failed():
        PISM.logging.logError("Inverse solve ended: %s\n"
                              "Writing partial results.\n"
                              % reason.nested_description(1))
    else:
        logMessage("Inverse solve success (%s)!\n"
                   % reason.description())

    (zeta, u) = solver.inverseSolution()

    # If the state solution is empty (e.g. after DIVERGED_MAXITS),
    # do a final forward solve with the current zeta to get velocities.
    if (u is not None
            and u.norm(PISM.PETSc.NormType.NORM_INFINITY)[0] == 0.0):
        logMessage("  State solution is zero; running final forward "
                   "solve.\n")
        solver.solveForward(zeta, u)

    # ── Convert zeta back to design variable ──────────────────────────

    if vecs.has(design_var):
        design = vecs.get(design_var)
        design_param.convertToDesignVariable(zeta, design)
    else:
        design = createDesignVec(grid, design_var)
        design_param.convertToDesignVariable(zeta, design)
        vecs.add(design, writing=True)

    zeta.metadata(0).set_name(zeta_name)
    vecs.add(zeta, writing=True)

    u.metadata(0).set_name("u_inv")
    u.metadata(0).set_string(
        "long_name",
        "x-component of velocity computed by inversion")
    u.metadata(0).units("m s^-1").output_units("m year^-1")

    u.metadata(1).set_name("v_inv")
    u.metadata(1).set_string(
        "long_name",
        "y-component of velocity computed by inversion")
    u.metadata(1).units("m s^-1").output_units("m year^-1")

    vecs.add(u, writing=True)

    # ── Compute residual ──────────────────────────────────────────────

    residual = PISM.model.create2dVelocityVec(grid, name='_inv_residual')
    residual.copy_from(u)
    residual.add(-1, vel_observed)

    r_mag = PISM.Scalar(grid, "inv_residual")
    r_mag.metadata(0).long_name(
        "magnitude of mismatch between observed and inverted velocities"
    ).units("m s^-1").output_units("m year^-1")
    r_mag.metadata().set_number("_FillValue",
                                 convert(-0.01, 'm/year', 'm/s'))
    r_mag.metadata().set_number("valid_min", 0.0)

    PISM.compute_magnitude(residual, r_mag)
    PISM.apply_mask(vecs.land_ice_thickness, 0.0, r_mag)

    vecs.add(residual, writing=True)
    vecs.add(r_mag, writing=True)

    # ── Compute beta (basal drag coefficient) ────────────────────────

    if design_var == "tauc":
        beta = PISM.Scalar(grid, "beta")
        beta.metadata(0).long_name(
            "basal drag coefficient (beta = tauc * f(|u|))"
        ).units("Pa s m^-1").output_units("Pa s m^-1")

        sliding_law = PISM.IceBasalResistancePseudoPlasticLaw(config)

        with PISM.vec.Access(comm=beta, nocomm=[design, u]):
            for (i, j) in grid.points():
                v = u(i, j)
                beta[i, j] = sliding_law.drag(design[i, j], v.u, v.v)

        vecs.add(beta, writing=True)

    # ── Write output ──────────────────────────────────────────────────

    forward_run.write(output_filename, append=True)
    misfit_logger.write(output_filename, suffix)

    misfit = misfit_logger.last_misfit()
    if alternating and misfit is not None:
        _write_global_attribute(output_filename,
                                "pismi_misfit_%s" % tag, "%.10g" % misfit)

    # Release the forward problem (3D DM, SNES, Jacobians, adjoint KSP)
    # before the next phase constructs its own.
    del solver
    del forward_run
    gc.collect()

    return misfit


def _run_alternating(opts, cycles, misfit_tol):
    """Alternate tauc and hardav inversions for ``cycles`` cycles.

    Each cycle inverts for ``tauc`` (with the current ``hardav`` held
    fixed) and then for ``hardav`` (with the new ``tauc`` held fixed).
    Phases hand their results to each other through the output file. The
    loop stops early once the relative misfit improvement over a full cycle
    drops below ``misfit_tol`` (``inverse.alternating_misfit_tol``).
    """
    output_filename = opts.output_filename

    # Resume: skip the phases recorded as completed in the output file, and
    # restart the phase that was interrupted from its last saved zeta. If the
    # interrupted phase never got as far as saving a zeta (e.g. it died while
    # reading its inputs), there is nothing to restart from: start it fresh,
    # which in alternation mode means from the previous phase's result.
    resume_from = (0, 0)
    restart_first = False
    if opts.do_restart:
        completed = _read_global_attribute(output_filename, _ALTERNATION_ATTR)
        if completed:
            c, var = completed.split("_", 1)
            c = int(c[1:])
            p = _ALTERNATION_PHASES.index(var) + 1
            if p == len(_ALTERNATION_PHASES):
                c, p = c + 1, 0
            resume_from = (c, p)
        first_var = _ALTERNATION_PHASES[resume_from[1]]
        restart_first = PISM.util.fileHasVariable(output_filename,
                                                  "zeta_inv_%s" % first_var)
        logMessage("  Resuming alternation at cycle %d, phase '%s'%s.\n"
                   % (resume_from[0], first_var,
                      "" if restart_first else " (no saved zeta; starting the phase fresh)"))

    prev_misfit = None
    for cycle in range(cycles):
        misfit = None
        for p, design_var in enumerate(_ALTERNATION_PHASES):
            if (cycle, p) < resume_from:
                continue
            misfit = _run_phase(opts, design_var,
                                restart=restart_first, cycle=cycle)
            restart_first = False
            _write_global_attribute(output_filename, _ALTERNATION_ATTR,
                                    "c%d_%s" % (cycle, design_var))

        if misfit is None:
            continue

        logMessage("Alternation cycle %d done: misfit %.8g\n" % (cycle, misfit))
        if prev_misfit is not None and prev_misfit > 0:
            improvement = (prev_misfit - misfit) / prev_misfit
            logMessage("  Relative misfit improvement over the cycle: %.4g\n"
                       % improvement)
            if improvement < misfit_tol:
                logMessage("  Below inverse.alternating_misfit_tol = %g; "
                           "stopping.\n" % misfit_tol)
                break
        prev_misfit = misfit


def _run():
    """Run the PISM inversion.

    Parses command-line options, prepares the output file and runs either a
    single-design-variable inversion (:func:`_run_phase`) or, when
    ``inverse.alternating_cycles`` is positive, alternating tauc/hardav
    inversions (:func:`_run_alternating`). The stress balance solver is
    selected via ``stress_balance.model`` (``ssa``, ``ssa+sia``, or
    ``blatter``).

    Fatal errors are reported as exceptions; `main()` turns them into an
    `MPI_Abort()`.
    """
    context = PISM.Context()
    config = context.config
    com = context.com
    PISM.set_abort_on_sigint(True)

    # ── Parse command-line options ─────────────────────────────────────

    input_filename = config.get_string("input.file")
    if len(input_filename) == 0:
        input_filename = None

    append = PISM.OptionString("-a", "append file")
    append_filename = append.value() if append.is_set() else None

    output_filename = config.get_string("output.file")
    if len(output_filename) == 0:
        output_filename = None

    append_mode = False

    if (input_filename is None) and (append_filename is None):
        PISM.verbPrintf(1, com,
                        "\nError: No input file specified."
                        " Use -i [file.nc] or -a [file.nc].\n")
        sys.exit(1)

    if (input_filename is not None) and (append_filename is not None):
        PISM.verbPrintf(1, com, "\nError: Only one of -i/-a is allowed.\n")
        sys.exit(1)

    if (output_filename is not None) and (append_filename is not None):
        PISM.verbPrintf(1, com, "\nError: Only one of -a/-o is allowed.\n")
        sys.exit(1)

    if append_filename is not None:
        input_filename = append_filename
        output_filename = append_filename
        append_mode = True

    # `inverse.file` is set by either -inverse.file or -inv_data (its
    # short `_option`), wired up automatically by set_config_from_options.
    inv_data_filename = config.get_string("inverse.file")
    if not inv_data_filename:
        inv_data_filename = input_filename

    # Design variable: `inverse.design.variable` (short option `-inv_design`)
    design_var = config.get_string("inverse.design.variable")

    # Also accept legacy flags for backwards compatibility
    legacy_ssa = PISM.OptionKeyword(
        "-inv_ssa", "design variable (legacy, use -inverse.design.variable)",
        "tauc,hardav", "tauc")
    legacy_blatter = PISM.OptionKeyword(
        "-inv_blatter", "design variable (legacy, use -inverse.design.variable)",
        "tauc,hardav", "tauc")
    if legacy_ssa.is_set():
        design_var = legacy_ssa.value()
    if legacy_blatter.is_set():
        design_var = legacy_blatter.value()

    do_restart = PISM.OptionBool("-inv_restart",
                                  "Restart a stopped computation.")
    remove_sia = PISM.OptionBool(
        "-remove_sia",
        "Subtract the SIA component (velsurf - vel_ssa) from observed "
        "velocities (SSA/hybrid only)")
    use_design_prior = config.get_flag("inverse.use_design_prior")
    using_zeta_fixed_mask = config.get_flag("inverse.use_zeta_fixed_mask")
    inv_method = config.get_string("inverse.stress_balance.method")

    # Determine solver type from stress balance model
    solver_type = config.get_string("stress_balance.model")
    if solver_type not in ('ssa', 'ssa+sia', 'blatter'):
        PISM.verbPrintf(1, com,
                        "\nError: stress_balance.model '%s' is not "
                        "supported for inversion.\n"
                        "Use 'ssa', 'ssa+sia', or 'blatter'.\n"
                        % solver_type)
        sys.exit(1)

    # Alternating tauc/hardav inversion. Only the Blatter forward problems
    # accept both design variables as inputs (the SSA tauc forward problem
    # always derives hardness from enthalpy).
    alternating_cycles = int(config.get_number("inverse.alternating_cycles"))
    misfit_tol = config.get_number("inverse.alternating_misfit_tol")
    if alternating_cycles > 0 and solver_type != 'blatter':
        PISM.verbPrintf(1, com,
                        "\nError: inverse.alternating_cycles = %d requires "
                        "stress_balance.model = 'blatter' (got '%s').\n"
                        % (alternating_cycles, solver_type))
        sys.exit(1)

    if output_filename is None:
        output_filename = "pismi_" + os.path.basename(input_filename)

    saving_inv_data = (inv_data_filename != output_filename)

    opts = Bunch(input_filename=input_filename,
                 inv_data_filename=inv_data_filename,
                 output_filename=output_filename,
                 append_mode=append_mode,
                 saving_inv_data=saving_inv_data,
                 do_restart=do_restart,
                 remove_sia=remove_sia,
                 use_design_prior=use_design_prior,
                 using_zeta_fixed_mask=using_zeta_fixed_mask,
                 inv_method=inv_method,
                 solver_type=solver_type)

    # ── Prepare output file ───────────────────────────────────────────

    message_logger = PISM.logging.CaptureLogger(output_filename,
                                                 'pismi_log')
    PISM.logging.add_logger(message_logger)
    if append_mode or do_restart:
        message_logger.readOldLog()

    if not append_mode and not do_restart:
        F = PISM.util.prepare_output(output_filename)
        # Write the grid mapping variable (CRS / spatial_ref) if available.
        # The grid is not known yet; the forward run writes it when it
        # writes the model vecs.
        F.close()
    PISM.util.writeProvenance(output_filename)

    PISM.verbPrintf(1, com,
                    "PISM inverse model (stress balance: %s).\n"
                    % solver_type)

    if alternating_cycles == 0:
        _run_phase(opts, design_var, restart=do_restart)
    else:
        PISM.verbPrintf(1, com,
                        "Alternating tauc/hardav inversion: %d cycle(s).\n"
                        % alternating_cycles)
        _run_alternating(opts, alternating_cycles, misfit_tol)

    if not append_mode:
        message_logger.write(output_filename)


def _abort(exit_code):
    """Terminate the whole MPI job immediately.

    A fatal error must not be allowed to unwind out of Python: the
    interpreter shutdown that follows runs petsc4py's `atexit` hook, which
    calls `PetscFinalize()` and therefore the *collective* `MPI_Finalize()`.
    Ranks reach that point at different times (and some tear down PISM
    objects that still hold PETSc handles first), so the job deadlocks
    instead of exiting -- under SLURM it then burns wall clock until the
    time limit or a `scancel`. The C++ driver (`src/pism.cc`) sidesteps
    this by catching everything in `main()` and returning an exit code.

    `MPI_Abort()` tears down every rank at once, so `mpirun` exits with a
    non-zero status and the calling script can stop.
    """
    sys.stdout.flush()
    sys.stderr.flush()
    MPI.COMM_WORLD.Abort(exit_code)


def main():
    """Run the inversion (console-script entry point).

    Wraps `_run()` so that any fatal error aborts all ranks instead of
    hanging in `MPI_Finalize()`.
    """
    try:
        _run()
    except SystemExit as e:
        # `sys.exit(0)` (or a bare `sys.exit()`) is a normal, successful
        # exit; anything else is fatal and must not unwind.
        code = e.code
        if code is None or code == 0:
            raise
        _abort(code if isinstance(code, int) else 1)
    except BaseException:
        # Errors here are usually collective (every rank fails on the same
        # bad option or missing file), so printing a full traceback per rank
        # buries the message. Report it once, in full, from rank 0.
        rank = MPI.COMM_WORLD.Get_rank()
        if rank == 0:
            sys.stderr.write("\nPISM ERROR: pismi failed:\n")
            traceback.print_exc()
        else:
            sys.stderr.write("PISM ERROR: pismi failed on rank %d: %s\n"
                             % (rank, sys.exc_info()[1]))
        _abort(1)


# Backwards-compatibility alias: external scripts that imported `run`
# (`from PISM.pismi import run`) keep working without modification.
run = main


if __name__ == "__main__":
    main()
